def _create_hypertables() -> None:
    """Turn time-series tables into TimescaleDB hypertables when the extension is installed.

    Plain Postgres (e.g. a local dev database or CI without Timescale) keeps regular tables,
    which behave identically for correctness, just slower at scale.
    """
    bind = op.get_bind()
    available = bind.execute(
        sa.text("SELECT 1 FROM pg_available_extensions WHERE name = 'timescaledb'")
    ).scalar()
    if not available:
        return
    op.execute("CREATE EXTENSION IF NOT EXISTS timescaledb")
    for table in ("daily_bars", "fx_rates"):
        op.execute(
            f"SELECT create_hypertable('{table}', by_range('date', INTERVAL '1 year'), "
            "create_default_indexes => false, migrate_data => true)"
        )


